1	package imagesearch
2	
3	import (
4		"context"
5		"errors"
6		"reflect"
7		"strings"
8		"testing"
9	
10		"github.com/anthnel/devdesk/internal/nexusfixture"
11		"github.com/anthnel/devdesk/internal/nexusfixture/fakenexus"
12		"github.com/anthnel/devdesk/internal/oci"
13	)
14	
15	// DEVDESK-511 (NX-08, step 4): the real CatalogSearcher over oci.ListCatalogContext
16	// walks the _catalog answers MEASURED on Nexus 3.98.1-01 (NX-03, DEVDESK-506),
17	// replayed by fakenexus, then Classify. Every expected verdict below comes from
18	// a fixture, not from a guess about Nexus.
19	//
20	// Out of scope here, because no measured answer exists yet: the verdict
21	// "failed" on a Nexus answer (a 5xx, an unreadable body), the mention "Cached
22	// only" (decided from the config by the UI package, and it needs the NX-04
23	// answers) and the Bearer flow on a catalog (NX-05). Nothing is invented to
24	// stand in for them.
25	
26	const (
27		nexusHTTPPort  = "127.0.0.1:30481" // REST API, /repository/<name>; hosted and proxy live here
28		nexusGroupPort = "127.0.0.1:30482" // the group's Docker connector
29	
30		// The member repositories of the bench, by the path under which they answer.
31		nexusHosted = "/repository/docker-hosted"
32		nexusProxy  = "/repository/docker-proxy"
33		nexusGroup  = "/repository/docker-group"
34	)
35	
36	// measuredIdentities are the three accounts every catalog was measured with: the
37	// answers are identical for all of them (NX-03, H2).
38	var measuredIdentities = []nexusfixture.Identity{nexusfixture.Admin, nexusfixture.Pull, nexusfixture.Anonymous}
39	
40	func loadCatalogFixtures(t *testing.T) []nexusfixture.Fixture {
41		t.Helper()
42		fixtures, err := nexusfixture.Load("catalog")
43		if err != nil {
44			t.Fatalf("Load(catalog): %v", err)
45		}
46		if len(fixtures) == 0 {
47			t.Fatal("the catalog campaign is empty")
48		}
49		return fixtures
50	}
51	
52	// answeringFixture is the fixture that answers DevDesk's "GET .../v2/_catalog?n=1000"
53	// for a scenario and an identity. Only the group connector's admin answer was
54	// recorded with n=1000 itself; every other one is a no-n recording that the
55	// fake lets answer n=1000 (the tolerance of fakenexus, measured on that one
56	// connector, inferred for hosted and proxy).
57	func answeringFixture(scenario string, id nexusfixture.Identity) string {
58		if scenario == "catalog-group-connector-30482" && id == nexusfixture.Admin {
59			return "page-group-n1000--admin"
60		}
61		return scenario + "--" + string(id)
62	}
63	
64	// totalHits counts every request answered by any fixture of the campaign.
65	func totalHits(s *fakenexus.Server, fixtures []nexusfixture.Fixture) int {
66		n := 0
67		for _, f := range fixtures {
68			n += s.Hits(f.Name)
69		}
70		return n
71	}
72	
73	// targetFor builds the entry a user would have: the API URL, the prefix and the
74	// credentials of the identity (none for anonymous).
75	func targetFor(apiURL, prefix string, id nexusfixture.Identity) Target {
76		tg := Target{APIURL: apiURL, RepoPrefix: prefix}
77		if id != nexusfixture.Anonymous {
78			tg.Username, tg.Password = fakenexus.User(id), fakenexus.Password
79		}
80		return tg
81	}
82	
83	func TestCatalogOnMeasuredNexusAnswers(t *testing.T) {
84		fixtures := loadCatalogFixtures(t)
85	
86		cases := []struct {
87			name     string
88			host     string // recorded Host whose fake server is walked
89			path     string // path kept by the entry's API URL ("" = the connector root)
90			scenario string // the fixture answering (see answeringFixture)
91			prefix   string
92			query    string
93			want     Verdict
94			rows     []string // Repo of each row, in the order Search returns them
95			prefixIs bool     // the error is ErrPrefixNotInCatalog (criterion 3)
96		}{
97			// The group connector: the one place where a root /v2/_catalog answers. Six
98			// names, none prefixed, the union of both members.
99			{
100				name: "group connector, api", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
101				query: "api", want: VerdictOK, rows: []string{"api", "team/api"},
102			},
103			{
104				// F1: the proxy relays its upstream's catalog, so a name it holds nothing
105				// of is listed: the search shows mirror/uncached.
106				name: "group connector, mirror", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
107				query: "mirror", want: VerdictOK, rows: []string{"mirror/cached", "mirror/uncached"},
108			},
109			{
110				name: "group connector, no match", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
111				query: "zz", want: VerdictNoResult,
112			},
113			{
114				// Criterion 3: R1 on a REAL, unprefixed catalog. Nexus lists "api", not
115				// "docker-hosted/api": no name carries the prefix, so the entry is refused
116				// (not "no result"). The same holds for the proxy member.
117				name: "group connector, prefix docker-hosted", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
118				prefix: "docker-hosted", query: "api", want: VerdictRefused, prefixIs: true,
119			},
120			{
121				name: "group connector, prefix docker-proxy", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
122				prefix: "docker-proxy", query: "mirror", want: VerdictRefused, prefixIs: true,
123			},
124	
125			// A member (or the group) reached by its own path: no prefix to apply.
126			{
127				name: "hosted by path, api", host: nexusHTTPPort, path: nexusHosted, scenario: "catalog-hosted-repository",
128				query: "api", want: VerdictOK, rows: []string{"api", "team/api"},
129			},
130			{
131				name: "hosted by path, mirror", host: nexusHTTPPort, path: nexusHosted, scenario: "catalog-hosted-repository",
132				query: "mirror", want: VerdictNoResult,
133			},
134			{
135				name: "proxy by path, mirror", host: nexusHTTPPort, path: nexusProxy, scenario: "catalog-proxy-repository",
136				query: "mirror", want: VerdictOK, rows: []string{"mirror/cached", "mirror/uncached"},
137			},
138			{
139				name: "proxy by path, api", host: nexusHTTPPort, path: nexusProxy, scenario: "catalog-proxy-repository",
140				query: "api", want: VerdictNoResult,
141			},
142			{
143				name: "group by path, api", host: nexusHTTPPort, path: nexusGroup, scenario: "catalog-group-repository",
144				query: "api", want: VerdictOK, rows: []string{"api", "team/api"},
145			},
146			{
147				// R1 again, through the by-path form: a Nexus member's catalog is never
148				// prefixed by the repository name either.
149				name: "hosted by path, prefix docker-hosted", host: nexusHTTPPort, path: nexusHosted, scenario: "catalog-hosted-repository",
150				prefix: "docker-hosted", query: "api", want: VerdictRefused, prefixIs: true,
151			},
152		}
153		for _, tc := range cases {
154			for _, id := range measuredIdentities {
155				t.Run(tc.name+" as "+string(id), func(t *testing.T) {
156					s := fakenexus.New(t, fixtures...)
157					tg := targetFor(s.URL(tc.host)+tc.path, tc.prefix, id)
158	
159					imgs, partial, err := CatalogSearcher{}.Search(context.Background(), tg, Query{Text: tc.query})
160					out := Classify(err, len(imgs), partial)
161	
162					if out.Verdict != tc.want {
163						t.Fatalf("verdict = %v, want %v (err = %v)", out.Verdict, tc.want, err)
164					}
165					if out.Partial || out.Skipped {
166						t.Errorf("marks = %+v, want none", out)
167					}
168					if got := errors.Is(err, ErrPrefixNotInCatalog); got != tc.prefixIs {
169						t.Errorf("errors.Is(err, ErrPrefixNotInCatalog) = %v, want %v (err = %v)", got, tc.prefixIs, err)
170					}
171					if tc.want != VerdictRefused && err != nil {
172						t.Errorf("err = %v, want nil", err)
173					}
174					var got []string
175					for _, im := range imgs {
176						got = append(got, im.Repo)
177						if im.Name != im.Repo {
178							t.Errorf("row %+v: Name differs from Repo with no prefix applied", im)
179						}
180					}
181					if !reflect.DeepEqual(got, tc.rows) {
182						t.Errorf("rows = %v, want %v", got, tc.rows)
183					}
184	
185					// Exactly one catalog request, answered by the expected recording.
186					if h := s.Hits(answeringFixture(tc.scenario, id)); h != 1 {
187						t.Errorf("Hits(%s) = %d, want 1", answeringFixture(tc.scenario, id), h)
188					}
189					if n := totalHits(s, fixtures); n != 1 {
190						t.Errorf("%d requests answered in total, want 1", n)
191					}
192				})
193			}
194		}
195	}
196	
197	// What discovery gives a Nexus group member is the HTTP port plus the member's
198	// prefix (registrymgr, step 5). DevDesk then asks the root of that port for
199	// /v2/_catalog?n=1000, where Nexus has no catalog at all: it answers 404 (an
200	// HTML page, measured as catalog-hosted-root-30481--*). The 404 comes before any
201	// filtering, so R1 is not reached: the verdict is refused, with a registry
202	// StatusError, not "no result" and not "failed".
203	//
204	// Pending (DEVDESK-580): the root 404 was recorded WITHOUT the "n=1000"
205	// DevDesk sends, and fakenexus deliberately does not let a recorded non-200
206	// answer an n=1000 request (TestCatalogTolerance, "a recorded 404 is not
207	// tolerated"). There is no measured fixture for GET /v2/_catalog?n=1000 on the
208	// root port of a hosted repository, and none is invented here. It is to be
209	// recorded on the bench through DEVDESK-580 (NX-08b) with `nexus-bench record`;
210	// remove the Skip below once that fixture exists, the body is ready to run.
211	func TestCatalogOnTheHTTPPortRootIsRefused(t *testing.T) {
212		fixtures := loadCatalogFixtures(t)
213		if !recordsTarget(fixtures, nexusHTTPPort, "/v2/_catalog?n=1000") {
214			t.Skip("pending DEVDESK-580 (NX-08b): no measured fixture for GET /v2/_catalog?n=1000 on the root port of a hosted repository; record it on the bench with `nexus-bench record` (this test runs by itself once it is recorded)")
215		}
216		for _, id := range measuredIdentities {
217			for _, prefix := range []string{"docker-hosted", "docker-proxy"} {
218				t.Run(prefix+" as "+string(id), func(t *testing.T) {
219					s := fakenexus.New(t, fixtures...)
220					tg := targetFor(s.URL(nexusHTTPPort), prefix, id)
221	
222					imgs, partial, err := CatalogSearcher{}.Search(context.Background(), tg, Query{Text: "api"})
223					if got := Classify(err, len(imgs), partial); got != (Outcome{Verdict: VerdictRefused}) {
224						t.Fatalf("outcome = %+v, want refused (err = %v)", got, err)
225					}
226					var se *oci.StatusError
227					if !errors.As(err, &se) || se.Code != 404 || se.Source != oci.SourceRegistry {
228						t.Errorf("err = %v (%T), want *oci.StatusError{404, SourceRegistry}", err, err)
229					}
230					if errors.Is(err, ErrPrefixNotInCatalog) {
231						t.Error("R1 was reached: there is no catalog to filter on this port")
232					}
233					if h := s.Hits("catalog-hosted-root-30481--" + string(id)); h != 1 {
234						t.Errorf("Hits(catalog-hosted-root-30481--%s) = %d, want 1", id, h)
235					}
236				})
237			}
238		}
239	}
240	
241	// recordsTarget reports whether a loaded fixture holds an exchange for exactly
242	// this target on this recorded Host, for any account: the tolerance of fakenexus
243	// is not a recording, and the test above needs the real answer.
244	func recordsTarget(fixtures []nexusfixture.Fixture, host, target string) bool {
245		for _, f := range fixtures {
246			for _, ex := range f.Exchanges {
247				if ex.Host == host && ex.Target == target {
248					return true
249				}
250			}
251		}
252		return false
253	}
254	
255	// The fixtures are measured with the three accounts and the answers do not
256	// depend on the identity (H2): a verdict that differed between them would mean a
257	// fixture, or the matching, changed. Guard the premise the table above relies on.
258	func TestMeasuredCatalogsDoNotDependOnTheAccount(t *testing.T) {
259		byName := map[string]nexusfixture.Fixture{}
260		for _, f := range loadCatalogFixtures(t) {
261			byName[f.Name] = f
262		}
263		for _, scenario := range []string{
264			"catalog-group-connector-30482", "catalog-group-repository",
265			"catalog-hosted-repository", "catalog-proxy-repository",
266		} {
267			admin := byName[scenario+"--admin"]
268			for _, id := range []nexusfixture.Identity{nexusfixture.Pull, nexusfixture.Anonymous} {
269				other := byName[scenario+"--"+string(id)]
270				if len(admin.Exchanges) != 1 || len(other.Exchanges) != 1 {
271					t.Fatalf("%s: want one exchange per account", scenario)
272				}
273				a, o := admin.Exchanges[0], other.Exchanges[0]
274				if a.Status != o.Status || string(a.Body) != string(o.Body) {
275					t.Errorf("%s: %s answers %d %q, admin %d %q", scenario, id, o.Status, o.Body, a.Status, a.Body)
276				}
277				if !strings.HasPrefix(string(a.Body), `{"repositories":[`) {
278					t.Errorf("%s: unexpected body %q", scenario, a.Body)
279				}
280			}
281		}
282	}
