86		cases := []struct {
87			name     string
88			host     string // recorded Host whose fake server is walked
89			path     string // path kept by the entry's API URL ("" = the connector root)
90			scenario string // the fixture answering (see answeringFixture)
91			prefix   string
92			query    string
93			want     Verdict
94			rows     []string // Repo of each row, in the order Search returns them
95			prefixIs bool     // the error is ErrPrefixNotInCatalog (criterion 3)
96		}{
97			// The group connector: the one place where a root /v2/_catalog answers. Six
98			// names, none prefixed, the union of both members.
99			{
100				name: "group connector, api", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
101				query: "api", want: VerdictOK, rows: []string{"api", "team/api"},
102			},
103			{
104				// F1: the proxy relays its upstream's catalog, so a name it holds nothing
105				// of is listed: the search shows mirror/uncached.
106				name: "group connector, mirror", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
107				query: "mirror", want: VerdictOK, rows: []string{"mirror/cached", "mirror/uncached"},
108			},
109			{
110				name: "group connector, no match", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
111				query: "zz", want: VerdictNoResult,
112			},
113			{
114				// Criterion 3: R1 on a REAL, unprefixed catalog. Nexus lists "api", not
115				// "docker-hosted/api": no name carries the prefix, so the entry is refused
116				// (not "no result"). The same holds for the proxy member.
117				name: "group connector, prefix docker-hosted", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
118				prefix: "docker-hosted", query: "api", want: VerdictRefused, prefixIs: true,
119			},
120			{
121				name: "group connector, prefix docker-proxy", host: nexusGroupPort, scenario: "catalog-group-connector-30482",
122				prefix: "docker-proxy", query: "mirror", want: VerdictRefused, prefixIs: true,
123			},
124	
125			// A member (or the group) reached by its own path: no prefix to apply.
126			{
127				name: "hosted by path, api", host: nexusHTTPPort, path: nexusHosted, scenario: "catalog-hosted-repository",
128				query: "api", want: VerdictOK, rows: []string{"api", "team/api"},
129			},
130			{
131				name: "hosted by path, mirror", host: nexusHTTPPort, path: nexusHosted, scenario: "catalog-hosted-repository",
132				query: "mirror", want: VerdictNoResult,
133			},
134			{
135				name: "proxy by path, mirror", host: nexusHTTPPort, path: nexusProxy, scenario: "catalog-proxy-repository",
136				query: "mirror", want: VerdictOK, rows: []string{"mirror/cached", "mirror/uncached"},
137			},
138			{
139				name: "proxy by path, api", host: nexusHTTPPort, path: nexusProxy, scenario: "catalog-proxy-repository",
140				query: "api", want: VerdictNoResult,
141			},
142			{
143				name: "group by path, api", host: nexusHTTPPort, path: nexusGroup, scenario: "catalog-group-repository",
144				query: "api", want: VerdictOK, rows: []string{"api", "team/api"},
145			},
146			{
147				// R1 again, through the by-path form: a Nexus member's catalog is never
148				// prefixed by the repository name either.
149				name: "hosted by path, prefix docker-hosted", host: nexusHTTPPort, path: nexusHosted, scenario: "catalog-hosted-repository",
150				prefix: "docker-hosted", query: "api", want: VerdictRefused, prefixIs: true,
151			},
152		}
153		for _, tc := range cases {
154			for _, id := range measuredIdentities {
155				t.Run(tc.name+" as "+string(id), func(t *testing.T) {
156					s := fakenexus.New(t, fixtures...)
157					tg := targetFor(s.URL(tc.host)+tc.path, tc.prefix, id)
158	
159					imgs, partial, err := CatalogSearcher{}.Search(context.Background(), tg, Query{Text: tc.query})
160					out := Classify(err, len(imgs), partial)
161	
162					if out.Verdict != tc.want {
163						t.Fatalf("verdict = %v, want %v (err = %v)", out.Verdict, tc.want, err)
164					}
165					if out.Partial || out.Skipped {
166						t.Errorf("marks = %+v, want none", out)
167					}
168					if got := errors.Is(err, ErrPrefixNotInCatalog); got != tc.prefixIs {
169						t.Errorf("errors.Is(err, ErrPrefixNotInCatalog) = %v, want %v (err = %v)", got, tc.prefixIs, err)
170					}
171					if tc.want != VerdictRefused && err != nil {
172						t.Errorf("err = %v, want nil", err)
173					}
174					var got []string
175					for _, im := range imgs {
176						got = append(got, im.Repo)
177						if im.Name != im.Repo {
178							t.Errorf("row %+v: Name differs from Repo with no prefix applied", im)
179						}
180					}
181					if !reflect.DeepEqual(got, tc.rows) {
