185					// Exactly one catalog request, answered by the expected recording.
186					if h := s.Hits(answeringFixture(tc.scenario, id)); h != 1 {
187						t.Errorf("Hits(%s) = %d, want 1", answeringFixture(tc.scenario, id), h)
188					}
189					if n := totalHits(s, fixtures); n != 1 {
190						t.Errorf("%d requests answered in total, want 1", n)
191					}
