197	// What discovery gives a Nexus group member is the HTTP port plus the member's
198	// prefix (registrymgr, step 5). DevDesk then asks the root of that port for
199	// /v2/_catalog?n=1000, where Nexus has no catalog at all: it answers 404 (an
200	// HTML page, measured as catalog-hosted-root-30481--*). The 404 comes before any
201	// filtering, so R1 is not reached: the verdict is refused, with a registry
202	// StatusError, not "no result" and not "failed".
203	//
204	// Pending (DEVDESK-580): the root 404 was recorded WITHOUT the "n=1000"
205	// DevDesk sends, and fakenexus deliberately does not let a recorded non-200
206	// answer an n=1000 request (TestCatalogTolerance, "a recorded 404 is not
207	// tolerated"). There is no measured fixture for GET /v2/_catalog?n=1000 on the
208	// root port of a hosted repository, and none is invented here. It is to be
209	// recorded on the bench through DEVDESK-580 (NX-08b) with `nexus-bench record`;
210	// remove the Skip below once that fixture exists, the body is ready to run.
211	func TestCatalogOnTheHTTPPortRootIsRefused(t *testing.T) {
212		fixtures := loadCatalogFixtures(t)
213		if !recordsTarget(fixtures, nexusHTTPPort, "/v2/_catalog?n=1000") {
214			t.Skip("pending DEVDESK-580 (NX-08b): no measured fixture for GET /v2/_catalog?n=1000 on the root port of a hosted repository; record it on the bench with `nexus-bench record` (this test runs by itself once it is recorded)")
215		}
216		for _, id := range measuredIdentities {
217			for _, prefix := range []string{"docker-hosted", "docker-proxy"} {
218				t.Run(prefix+" as "+string(id), func(t *testing.T) {
219					s := fakenexus.New(t, fixtures...)
220					tg := targetFor(s.URL(nexusHTTPPort), prefix, id)
221	
222					imgs, partial, err := CatalogSearcher{}.Search(context.Background(), tg, Query{Text: "api"})
223					if got := Classify(err, len(imgs), partial); got != (Outcome{Verdict: VerdictRefused}) {
224						t.Fatalf("outcome = %+v, want refused (err = %v)", got, err)
225					}
226					var se *oci.StatusError
227					if !errors.As(err, &se) || se.Code != 404 || se.Source != oci.SourceRegistry {
228						t.Errorf("err = %v (%T), want *oci.StatusError{404, SourceRegistry}", err, err)
229					}
230					if errors.Is(err, ErrPrefixNotInCatalog) {
231						t.Error("R1 was reached: there is no catalog to filter on this port")
232					}
233					if h := s.Hits("catalog-hosted-root-30481--" + string(id)); h != 1 {
234						t.Errorf("Hits(catalog-hosted-root-30481--%s) = %d, want 1", id, h)
235					}
236				})
237			}
238		}
239	}
