241	// recordsTarget reports whether a loaded fixture holds an exchange for exactly
242	// this target on this recorded Host, for any account: the tolerance of fakenexus
243	// is not a recording, and the test above needs the real answer.
244	func recordsTarget(fixtures []nexusfixture.Fixture, host, target string) bool {
245		for _, f := range fixtures {
246			for _, ex := range f.Exchanges {
247				if ex.Host == host && ex.Target == target {
248					return true
249				}
250			}
251		}
252		return false
253	}
