18	// These tests pin the batch memo (DEVDESK-311, IS-07): members of one batch
19	// that reach the same catalog with the same identity share one walk.
20	
21	// countingLister counts its calls; when gate is set, each call blocks on it
22	// (after signalling entered) so a test can force concurrency.
23	type countingLister struct {
24		names     []string
25		truncated bool
26		err       error
27	
28		calls   atomic.Int32
29		entered chan struct{}
30		gate    chan struct{}
31		mu      sync.Mutex
32		seen    []string // apiURL|user|pass per call
33	}
34	
35	func (f *countingLister) list(ctx context.Context, apiURL, user, pass string, _, _ int) ([]string, bool, error) {
36		f.calls.Add(1)
37		f.mu.Lock()
38		f.seen = append(f.seen, apiURL+"|"+user+"|"+pass)
39		f.mu.Unlock()
40		if f.entered != nil {
41			select {
42			case f.entered <- struct{}{}:
43			default:
44			}
45		}
46		if f.gate != nil {
47			select {
48			case <-f.gate:
49			case <-ctx.Done():
50				return nil, false, ctx.Err()
51			}
52		}
53		return f.names, f.truncated, f.err
54	}
