60	type result struct {
61		imgs    []Image
62		partial bool
63		err     error
64	}
65	
66	func searchAll(ctx context.Context, f *countingLister, targets []Target, text string) []result {
67		out := make([]result, len(targets))
68		var wg sync.WaitGroup
69		for i, tg := range targets {
70			wg.Add(1)
71			go func() {
72				defer wg.Done()
73				imgs, partial, err := CatalogSearcher{List: f.list}.Search(ctx, tg, Query{Text: text})
74				out[i] = result{imgs, partial, err}
75			}()
76		}
77		wg.Wait()
78		return out
79	}
