81	func TestSharedWalkParallelMembersOneCall(t *testing.T) {
82		f := &countingLister{
83			names:   []string{"a/app", "b/app", "c/app", "a/api", "other/app"},
84			entered: make(chan struct{}, 8),
85			gate:    make(chan struct{}),
86		}
87		ctx := WithSharedWalks(context.Background())
88		targets := []Target{member("k-a", "a", "u", "p"), member("k-b", "b", "u", "p"), member("k-c", "c", "u", "p")}
89		done := make(chan []result)
90		go func() { done <- searchAll(ctx, f, targets, "app") }()
91		<-f.entered
92		time.Sleep(100 * time.Millisecond) // let the followers join
93		close(f.gate)
94		res := <-done
95		if got := f.calls.Load(); got != 1 {
96			t.Fatalf("walks = %d, want 1 (AC1)", got)
97		}
98		for i, want := range []struct{ key, repo string }{{"k-a", "a/app"}, {"k-b", "b/app"}, {"k-c", "c/app"}} {
99			r := res[i]
100			if r.err != nil || len(r.imgs) != 1 {
101				t.Fatalf("member %s: %+v", want.key, r)
102			}
103			if r.imgs[0].EntryKey != want.key || r.imgs[0].Repo != want.repo || r.imgs[0].Name != "app" {
104				t.Errorf("member %s got %+v (AC2)", want.key, r.imgs[0])
105			}
106		}
107	}
