type requestLog struct {
	mu    sync.Mutex
	uris  []string
	auths []string
}

func (l *requestLog) add(r *http.Request) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.uris = append(l.uris, r.RequestURI)
	l.auths = append(l.auths, r.Header.Get("Authorization"))
}

