		name   string
		prefix string
	}{
		{"empty", ""},
		{"only slashes", "///"},
		{"dot-dot", ".."},
		{"dot-dot inside", "a/../b"},
		{"dot", "."},
		{"dot segment", "a/./b"},
		{"empty segment", "a//b"},
		{"leading slash", "/a"},
		{"trailing slash", "a/"},
		{"space", "my repo"},
		{"percent", "a%2fb"},
		{"backslash", `a\b`},
		{"query", "a?b"},
		{"control character", "a\x1b[31m"},
		{"NUL", "a\x00b"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
